def do_PUT(self):
    parsed = urlparse(self.path)
    path = parsed.path
    # Handle full update: PUT /books/<id>
    book_id_path = path.split('/')
    if len(book_id_path) == 2 and book_id_path[1].isdigit():
        book_id = int(book_id_path[1])
    elif path == "/books":
        # Handle create/update without id
        book_id = None
    else:
        self.send_error(404)
        return

    content_length = int(self.headers.get('Content-Length', 0))
    if content_length == 0:
        self.send_error(400, "empty body")
        return

    try:
        data = json.loads(self.rfile.read(content_length))
    except json.JSONDecodeError:
        self.send_error(400, "invalid JSON")
        return

    if not isinstance(data, dict):
        self.send_error(400, "body must be JSON object")
        return
